ALTER TABLE public.opportunities ADD COLUMN description text NOT NULL DEFAULT '', ADD COLUMN service_category text NOT NULL DEFAULT '', ADD COLUMN budget numeric, ADD COLUMN currency text, ADD COLUMN application_url text, ADD COLUMN application_instructions text NOT NULL DEFAULT '', ADD COLUMN closing_date date, ADD COLUMN status text NOT NULL DEFAULT 'draft', ADD COLUMN origin text NOT NULL DEFAULT 'external', ADD COLUMN discovery_section text NOT NULL DEFAULT 'web', ADD COLUMN updated_at timestamptz NOT NULL DEFAULT now();
UPDATE public.opportunities SET status = CASE WHEN published THEN 'published' ELSE 'draft' END, discovery_section = CASE WHEN EXISTS (SELECT 1 FROM public.sources s WHERE s.id=source_id AND s.platform <> 'Web') THEN 'social' ELSE 'web' END;
ALTER TABLE public.opportunities ADD CONSTRAINT opportunities_status_valid CHECK (status IN ('draft','published','expired','archived')), ADD CONSTRAINT opportunities_origin_valid CHECK (origin IN ('external','direct')), ADD CONSTRAINT opportunities_section_valid CHECK (discovery_section IN ('social','web','direct')), ADD CONSTRAINT opportunities_budget_valid CHECK (budget IS NULL OR budget >= 0), ADD CONSTRAINT opportunities_currency_valid CHECK (currency IS NULL OR currency ~ '^[A-Z]{3}$'), ADD CONSTRAINT opportunities_origin_section CHECK ((origin='direct' AND discovery_section='direct') OR (origin='external' AND discovery_section IN ('social','web'))), ADD CONSTRAINT opportunities_urls_valid CHECK ((url IS NULL OR url ~* '^https?://[^[:space:]]+$') AND (application_url IS NULL OR application_url ~* '^https?://[^[:space:]]+$'));
ALTER TABLE public.sources ADD COLUMN integration_configured boolean NOT NULL DEFAULT false;
REVOKE INSERT,UPDATE,DELETE ON public.sources FROM authenticated;
GRANT INSERT (name,platform,enabled), UPDATE (name,platform,enabled) ON public.sources TO authenticated;
CREATE TABLE public.admin_audit (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), actor_id uuid NOT NULL, opportunity_id uuid NOT NULL, action text NOT NULL, before_value jsonb, after_value jsonb, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.admin_audit TO authenticated;
GRANT ALL ON public.admin_audit TO service_role;
ALTER TABLE public.admin_audit ENABLE ROW LEVEL SECURITY;
CREATE POLICY audit_admin_read ON public.admin_audit FOR SELECT TO authenticated USING (public.has_role((SELECT auth.uid()),'admin'));
CREATE OR REPLACE FUNCTION public.opportunity_is_active(o public.opportunities) RETURNS boolean LANGUAGE sql STABLE SET search_path=public AS $$ SELECT o.published AND o.status='published' AND (o.closing_date IS NULL OR o.closing_date >= CURRENT_DATE) $$;
DROP POLICY opportunities_read ON public.opportunities;
CREATE POLICY opportunities_read ON public.opportunities FOR SELECT TO authenticated USING (public.opportunity_is_active(opportunities) OR public.has_role((SELECT auth.uid()),'admin'));
DROP POLICY saves_create ON public.saved_opportunities;
CREATE POLICY saves_create ON public.saved_opportunities FOR INSERT TO authenticated WITH CHECK (user_id=(SELECT auth.uid()) AND EXISTS (SELECT 1 FROM public.opportunities o WHERE o.id=opportunity_id AND public.opportunity_is_active(o)));
DROP POLICY tracker_owner ON public.tracked_applications;
CREATE POLICY tracker_owner ON public.tracked_applications FOR ALL TO authenticated USING (user_id=(SELECT auth.uid())) WITH CHECK (user_id=(SELECT auth.uid()) AND (opportunity_id IS NULL OR EXISTS (SELECT 1 FROM public.opportunities o WHERE o.id=opportunity_id)));
CREATE OR REPLACE FUNCTION public.prepare_opportunity() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN NEW.published := NEW.status='published'; NEW.updated_at:=now(); IF NEW.status='published' AND (length(trim(NEW.description))=0 OR length(trim(NEW.summary))=0 OR (NEW.application_url IS NULL AND length(trim(NEW.application_instructions))=0) OR (NEW.origin='external' AND (NEW.source_id IS NULL OR NEW.url IS NULL))) THEN RAISE EXCEPTION 'Published opportunities require description, summary, application information and an external source when applicable'; END IF; IF NEW.origin='external' AND NEW.source_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.sources s WHERE s.id=NEW.source_id AND ((NEW.discovery_section='web' AND s.platform='Web') OR (NEW.discovery_section='social' AND s.platform<>'Web'))) THEN RAISE EXCEPTION 'Source does not match discovery section'; END IF; RETURN NEW; END $$;
CREATE TRIGGER prepare_opportunity BEFORE INSERT OR UPDATE ON public.opportunities FOR EACH ROW EXECUTE FUNCTION public.prepare_opportunity();
CREATE OR REPLACE FUNCTION public.audit_opportunity() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NOT NULL THEN INSERT INTO public.admin_audit(actor_id,opportunity_id,action,before_value,after_value) VALUES(auth.uid(),COALESCE(NEW.id,OLD.id),TG_OP,CASE WHEN TG_OP='INSERT' THEN NULL ELSE to_jsonb(OLD) END,CASE WHEN TG_OP='DELETE' THEN NULL ELSE to_jsonb(NEW) END); END IF; RETURN COALESCE(NEW,OLD); END $$;
CREATE TRIGGER audit_opportunity AFTER INSERT OR UPDATE OR DELETE ON public.opportunities FOR EACH ROW EXECUTE FUNCTION public.audit_opportunity();
CREATE OR REPLACE FUNCTION public.admin_overview() RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Forbidden' USING ERRCODE='42501'; END IF; RETURN jsonb_build_object('registered_users',(SELECT count(*) FROM auth.users),'published_opportunities',(SELECT count(*) FROM public.opportunities o WHERE public.opportunity_is_active(o)),'draft_opportunities',(SELECT count(*) FROM public.opportunities WHERE status='draft'),'archived_opportunities',(SELECT count(*) FROM public.opportunities WHERE status='archived'),'saved_opportunities',(SELECT count(*) FROM public.saved_opportunities),'tracked_applications',(SELECT count(*) FROM public.tracked_applications)); END $$;
REVOKE ALL ON FUNCTION public.admin_overview() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.admin_overview() TO authenticated;
REVOKE ALL ON FUNCTION public.audit_opportunity() FROM PUBLIC,anon,authenticated;
CREATE INDEX opportunities_discovery_active ON public.opportunities(discovery_section,status,posted_at);
CREATE INDEX opportunities_skills ON public.opportunities USING gin(skills);